-- Seed del catálogo consolidado (Catalogo_Pilares_v3): 25 familias → plantillas + mapeo del tarifario.
-- Requiere migración 0011.

create or replace function pg_temp.seed_pl(p_id uuid, p_nombre text, p_desc text, p_tipo tipo_plantilla_t, p_pilar text, p_familia text, p_unidad text, p_precio text, p_rec boolean, p_patron text, p_bloques jsonb)
returns void language plpgsql as $$
declare b jsonb; t jsonb; v_pl uuid; v_bloque uuid; i int := 0; j int;
begin
  values (p_id, '00000000-0000-4000-8000-000000000001', p_nombre, p_desc, p_tipo, p_pilar, p_familia, p_unidad, p_precio, p_rec, p_patron)
  on conflict (tenant_id, nombre) do update set descripcion = excluded.descripcion, tipo = excluded.tipo, pilar = excluded.pilar, familia = excluded.familia, unidad = excluded.unidad, precio_referencia = excluded.precio_referencia, recurrente = excluded.recurrente, patron_nombre = excluded.patron_nombre;
  select id into v_pl from plantillas where tenant_id = '00000000-0000-4000-8000-000000000001' and nombre = p_nombre;
  delete from plantilla_bloques where plantilla_id = v_pl;
  for b in select * from jsonb_array_elements(p_bloques) loop
    i := i + 1;
    values ('00000000-0000-4000-8000-000000000001', v_pl, b->>'nombre', (b->>'peso')::numeric, i, coalesce((b->>'opcional')::boolean, false))
    returning id into v_bloque;
    j := 0;
    for t in select * from jsonb_array_elements(b->'tareas') loop
      j := j + 1;
      values ('00000000-0000-4000-8000-000000000001', v_bloque, t->>'titulo', t->>'etiqueta', (t->>'etiqueta') is not null, coalesce((t->>'peso')::numeric,1), coalesce((t->>'offset')::int,0), t->>'rol', j);
    end loop;
  end loop;
end $$;

